\begin{bmatrix}\frac12 & \mp \frac{\sqrt{3}}{2}\\ 
\pm\frac{\sqrt{3}}{2} & \frac12\end{bmatrix} 
\begin{bmatrix}x_2-x_1\\ y_2-y_1\end{bmatrix}
$$ 
